import type { Bus } from '../core/bus'
import { COLOR } from '../core/theme'
import type { ColorName } from '../core/theme'

/* ============================================================================
 * THE KEYBOARD MAP AND THE COLOUR LEGEND
 *
 * The legend is generated by walking COLOR itself, so it cannot drift from
 * what the city renders: a hue added to the palette appears here immediately,
 * with its key as its label until somebody writes down what it means. A legend
 * maintained by hand would eventually describe a city that no longer exists.
 * ==========================================================================*/

export interface Help {
  dispose(): void
}

interface KeyRow {
  /** Rendered as separate <kbd> elements. */
  k: string[]
  /** How the keys relate: pressed together, or alternatives. */
  j?: string
  d: string
}

interface KeySection {
  title: string
  rows: KeyRow[]
}

