const GROUP_ORDER: readonly string[] = [
  'The one idea',
  'Control plane',
  'Data plane',
  'Health',
  'Structure, which carries no meaning',
  'Not yet described',
]

function hex(n: number): string {
  return `#${n.toString(16).padStart(6, '0')}`
}

function el<K extends keyof HTMLElementTagNameMap>(
  tag: K,
  cls?: string,
  text?: string,
): HTMLElementTagNameMap[K] {
  const node = document.createElement(tag)
  if (cls) node.className = cls
  if (text !== undefined) node.textContent = text
  return node
}

export function createHelp(bus: Bus): Help {
  if (typeof document === 'undefined') return { dispose: () => {} }
  const host = document.getElementById('help')
  if (!host) {
    console.warn('[ui/help] #help is missing from the document; key map disabled')
    return { dispose: () => {} }
  }

  const scrim = el('div', 'ovl-scrim')
  const sheet = el('div', 'ovl-sheet help')
  sheet.setAttribute('role', 'dialog')
  sheet.setAttribute('aria-label', 'Input map and colour legend')

  const head = el('header', 'ovl-head')
  head.append(el('h2', 'ovl-title', 'Controls and colour'))
  const close = el('button', 'ovl-close', '✕')
  close.type = 'button'
  close.setAttribute('aria-label', 'Close')
  head.append(close)

  const scroll = el('div', 'ovl-scroll')

  /* ------------------------------------------------------------ the key map */

  const keys = el('div', 'help-keys')
  for (const section of KEYMAP) {
    const block = el('section', 'help-block')
    block.appendChild(el('h3', 'help-h', section.title))
    const table = el('div', 'help-table')
    for (const row of section.rows) {
      const line = el('div', 'help-row')
      const keyCell = el('div', 'help-kcell')
      for (let i = 0; i < row.k.length; i++) {
        if (i > 0) keyCell.appendChild(el('span', 'help-join', row.j ?? ' '))
        keyCell.appendChild(el('kbd', undefined, row.k[i]))
      }
      line.append(keyCell, el('div', 'help-d', row.d))
      table.appendChild(line)
    }
    block.appendChild(table)
    keys.appendChild(block)
  }

  /* ------------------------------------------------------------ the legend */

  const legend = el('div', 'help-legend')
  legend.appendChild(el('h3', 'help-h', 'Colour is semantic, never decorative'))
  legend.appendChild(
    el(
      'p',
      'help-note',
      'Every swatch below is read straight out of the palette the city renders with. At night, structure is matte and meaning glows; only an emissive above 1.0 crosses the bloom threshold, so a glow always carries information.',
    ),
  )

  const buckets = new Map<string, ColorName[]>()
  const names = Object.keys(COLOR) as ColorName[]
  for (const name of names) {
    const group = GROUP[name] ?? 'Not yet described'
    const bucket = buckets.get(group)
    if (bucket) bucket.push(name)
    else buckets.set(group, [name])
  }
  /* Fixed order first, then any group the palette grew that nobody has filed. */
  const groups: string[] = []
  for (const g of GROUP_ORDER) if (buckets.has(g)) groups.push(g)
  for (const g of buckets.keys()) if (!groups.includes(g)) groups.push(g)

  for (const group of groups) {
    const block = el('section', 'help-block')
    block.appendChild(el('h4', 'help-sub', group))
    const grid = el('div', 'help-swatches')
    for (const name of buckets.get(group) ?? []) {
      const value = COLOR[name]
      const item = el('div', 'help-swatch')
      const chip = el('span', 'help-chip')
      chip.style.background = hex(value)
      const body = el('div', 'help-swatch-body')
      body.append(
        el('span', 'help-swatch-name', name),
        el('span', 'help-swatch-desc', MEANING[name] ?? 'No meaning has been written for this colour yet.'),
      )
      item.append(chip, body, el('code', 'help-swatch-hex', hex(value)))
      grid.appendChild(item)
    }
    block.appendChild(grid)
    legend.appendChild(block)
  }

  const footer = el(
    'p',
    'help-foot',
    'K8Skylines is a model, not an emulator. No Kubernetes code runs in this page; durations are scaled so a person can watch them, and every simplification that could change the lesson is written into the inspector for the mechanism it affects.',
  )

  scroll.append(keys, legend, footer)
  sheet.append(head, scroll)
  host.append(scrim, sheet)
  host.hidden = true

  /* ------------------------------------------------------------------ open */

  let isOpen = false

  const setOpen = (next: boolean): void => {
    if (next === isOpen) return
    isOpen = next
    host.hidden = !next
    bus.emit('overlay', { id: 'help', open: next })
    if (next) scroll.scrollTop = 0
  }

  const onClick = (ev: MouseEvent): void => {
    const target = ev.target
    if (target === scrim || target === close) setOpen(false)
  }
  host.addEventListener('click', onClick)

  const typing = (ev: KeyboardEvent): boolean => {
    const t = ev.target
    if (!(t instanceof HTMLElement)) return false
    return t.isContentEditable || t.tagName === 'INPUT' || t.tagName === 'TEXTAREA'
  }

  const onKey = (ev: KeyboardEvent): void => {
    if (typing(ev)) return
    if (isOpen && ev.key === 'Escape') {
      ev.preventDefault()
      ev.stopPropagation()
      setOpen(false)
      return
    }
    if (!isOpen && ev.key === '?') {
      ev.preventDefault()
      ev.stopPropagation()
      setOpen(true)
    }
  }
  window.addEventListener('keydown', onKey, true)

  const offOverlay = bus.on('overlay', (p) => {
    if (p.id === 'help') setOpen(p.open)
    else if (p.open && (p.id === 'search' || p.id === 'tour')) setOpen(false)
  })

  return {
    dispose(): void {
      offOverlay()
      host.removeEventListener('click', onClick)
      window.removeEventListener('keydown', onKey, true)
      host.textContent = ''
      host.hidden = true
      isOpen = false
    },
  }
}
